require("Demo.MVC.ResultWindow");

ResultController = class("ResultController", WindowController)


local instance;

function ResultController:ctor()
    self.super:ctor();
end

function ResultController:OnViewLoad()
    Debug.Log("ResultController开始加载...");
    EventDelegate.Add(self.view.buttonRetry.onClick, EventDelegate.Callback(function() self:OnRestart(); end));
    EventDelegate.Add(self.view.buttonQuit.onClick, EventDelegate.Callback(function() self:OnQuit(); end));
end

function ResultController.Instance()
    if instance == nil then
        instance = ResultController.new();
    end
    return instance;
end

function ResultController:OnRestart()
    self:HideWindow();
    GameController.Instance():Reset();
end

function ResultController:OnQuit()
    self:HideWindow();
    stageSystem.Instance:ChangeStage(StageSystem.Lobby);
end
